# Циклическая очередь фиксированного размера на кольцевом буфере
class CircularQueue:
    def __init__(self, k: int):
        self.k = k
        self.queue = [0] * k
        self.head = 0
        self.count = 0

    def enqueue(self, value: int) -> bool:
        if self.is_full():
            return False
        tail = (self.head + self.count) % self.k
        self.queue[tail] = value
        self.count += 1
        return True

    def dequeue(self) -> bool:
        if self.is_empty():
            return False
        self.head = (self.head + 1) % self.k
        self.count -= 1
        return True

    def front(self) -> int:
        return -1 if self.is_empty() else self.queue[self.head]

    def rear(self) -> int:
        if self.is_empty():
            return -1
        tail = (self.head + self.count - 1) % self.k
        return self.queue[tail]

    def is_empty(self) -> bool:
        return self.count == 0

    def is_full(self) -> bool:
        return self.count == self.k

cq = CircularQueue(3)
cq.enqueue(1); cq.enqueue(2)
print('Front:', cq.front(), 'Rear:', cq.rear())

