# Задача о размене монет (Coin Change DP)
def coin_change(
    coins: list, amount: int
) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(
                dp[x], dp[x - coin] + 1
            )
    res = dp[amount]
    return res if res != float('inf') else -1

