def counting_sort(nums: list[int], min_val: int, max_val: int) -> list[int]:
    if not nums:
        return []
    size = max_val - min_val + 1
    counts = [0] * size
    for n in nums:
        counts[n - min_val] += 1
    res = []
    for val_offset, cnt in enumerate(counts):
        if cnt > 0:
            res.extend([val_offset + min_val] * cnt)
    return res

