def max_path_sum(root: dict | None) -> int:
    if not root:
        return 0
    max_sum = float('-inf')
    def post_order(node: dict | None) -> int:
        nonlocal max_sum
        if not node:
            return 0
        left_gain = max(post_order(node.get('left')), 0)
        right_gain = max(post_order(node.get('right')), 0)
        price_new_path = node['val'] + left_gain + right_gain
        if price_new_path > max_sum:
            max_sum = price_new_path
        return node['val'] + max(left_gain, right_gain)
    post_order(root)
    return int(max_sum)

