        if current_time > self.last_time:
            delta = current_time - self.last_time
            self.tokens = min(self.capacity, self.tokens + delta * self.refill_rate)
            self.last_time = current_time
        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        return False

