def analyze_graph_density(n: int, edges: list[tuple[int, int]], directed: bool = False) -> dict[str, float | str | int]:
    unique = set()
    for u, v in edges:
        if 0 <= u < n and 0 <= v < n and u != v:
            if directed:
                unique.add((u, v))
            else:
                unique.add((min(u, v), max(u, v)))
    count = len(unique)
    if n < 2:
        return {'unique_edges': 0, 'density': 0.0, 'density_class': 'sparse'}
    max_edges = n * (n - 1) if directed else n * (n - 1) / 2
    density = round(count / max_edges, 4) if max_edges > 0 else 0.0
    density_class = 'dense' if density >= 0.5 else 'sparse'
    return {'unique_edges': count, 'density': density, 'density_class': density_class}

