import heapq

def dijkstra_shortest_paths(adj: dict[int, list[tuple[int, int]]], start: int) -> dict[int, int]:
    if start not in adj:
        return {}
    distances = {u: float('inf') for u in adj}
    distances[start] = 0
    pq = [(0, start)]
    while pq:
        curr_d, u = heapq.heappop(pq)
        if curr_d > distances[u]:
            continue
        for nbr, weight in adj.get(u, []):
            new_dist = curr_d + weight
            if new_dist < distances[nbr]:
                distances[nbr] = new_dist
                heapq.heappush(pq, (new_dist, nbr))
    return {u: int(d) for u, d in distances.items() if d != float('inf')}

