def find_bfs_path(adj: dict[int, list[int]], start: int, target: int) -> list[int]:
    if start not in adj or target not in adj:
        return []
    if start == target:
        return [start]
    queue = deque([start])
    parent = {start: None}
    found = False
    while queue:
        curr = queue.popleft()
        if curr == target:
            found = True
            break
        for nbr in sorted(adj.get(curr, [])):
            if nbr not in parent:
                parent[nbr] = curr
                queue.append(nbr)
    if not found and target not in parent:
        return []
    path = []
    curr = target
    while curr is not None:
        path.append(curr)
        curr = parent.get(curr)
    return path[::-1]

