def has_directed_cycle(adj: dict[int, list[int]]) -> bool:
    # 0 = unvisited, 1 = visiting (in stack), 2 = visited
    state = {u: 0 for u in adj}

    def dfs(u: int) -> bool:
        state[u] = 1
        for v in adj.get(u, []):
            if v not in state:
                continue
            if state[v] == 1:
                return True
            if state[v] == 0:
                if dfs(v):
                    return True
        state[u] = 2
        return False

    for node in adj:
        if state[node] == 0:
            if dfs(node):
                return True
    return False

