from collections import deque

def simulate_network_broadcast(network: dict[int, list[int]], emitters: list[int]) -> dict[str, int | dict[int, int]]:
    if not network:
        return {'delivery_times': {}, 'max_time': 0, 'unreachable_count': 0}
    delivery_times = {}
    queue = deque()
    for em in emitters:
        if em in network and em not in delivery_times:
            delivery_times[em] = 0
            queue.append((em, 0))
    while queue:
        curr, t = queue.popleft()
        for nbr in sorted(network.get(curr, [])):
            if nbr in network and nbr not in delivery_times:
                delivery_times[nbr] = t + 1
                queue.append((nbr, t + 1))
    unreachable = len(network) - len(delivery_times)
    max_t = max(delivery_times.values()) if delivery_times else 0
    return {
        'delivery_times': delivery_times,
        'max_time': max_t,
        'unreachable_count': unreachable
    }

