import heapq

def top_k_largest(nums: list[int], k: int) -> list[int]:
    if k <= 0 or not nums:
        return []
    if k >= len(nums):
        return sorted(nums, reverse=True)
    heap = []
    for x in nums:
        if len(heap) < k:
            heapq.heappush(heap, x)
        elif x > heap[0]:
            heapq.heapreplace(heap, x)
    res = []
    while heap:
        res.append(heapq.heappop(heap))
    return res[::-1]

