class StreamMedianTracker:
    def __init__(self):
        # max_heap хранит меньшую половину (инвертированные значения)
        self.small = []
        # min_heap хранит большую половину
        self.large = []

    def add_num(self, num: int) -> None:
        if not self.small or num <= -self.small[0]:
            heapq.heappush(self.small, -num)
        else:
            heapq.heappush(self.large, num)
        # Балансировка: размер small может быть равен large или на 1 больше
        if len(self.small) > len(self.large) + 1:
            val = -heapq.heappop(self.small)
            heapq.heappush(self.large, val)
        elif len(self.large) > len(self.small):
            val = heapq.heappop(self.large)
            heapq.heappush(self.small, -val)

    def get_median(self) -> float:
        if not self.small and not self.large:
            raise ValueError("No numbers added")
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2.0

