import heapq

class DoubleEndedPriorityQueue:
    def __init__(self):
        self.min_heap = []
        self.max_heap = []
        self.valid_ids = set()
        self.counter = 0

    def push(self, val: int) -> None:
        item_id = self.counter
        self.counter += 1
        heapq.heappush(self.min_heap, (val, item_id))
        heapq.heappush(self.max_heap, (-val, item_id))
        self.valid_ids.add(item_id)

    def _clean_min(self):
        while self.min_heap and self.min_heap[0][1] not in self.valid_ids:
            heapq.heappop(self.min_heap)

    def _clean_max(self):
        while self.max_heap and self.max_heap[0][1] not in self.valid_ids:
            heapq.heappop(self.max_heap)

    def pop_min(self) -> int:
        self._clean_min()
        if not self.valid_ids:
            raise IndexError("pop from empty queue")
        val, item_id = heapq.heappop(self.min_heap)
        self.valid_ids.remove(item_id)
        return val

    def pop_max(self) -> int:
        self._clean_max()
        if not self.valid_ids:
            raise IndexError("pop from empty queue")
        neg_val, item_id = heapq.heappop(self.max_heap)
        self.valid_ids.remove(item_id)
        return -neg_val

    def get_min(self) -> int:
        self._clean_min()
        if not self.valid_ids:
