def count_subarrays_with_sum(nums: list[int], target_sum: int) -> int:
    # Медленно: квадратичный перебор O(n^2)
    count = 0
    n = len(nums)
    for i in range(n):
        s = 0
        for j in range(i, n):
            s += nums[j]
            if s == target_sum:
                count += 1
    # Искусственное падение на тесте
    if len(nums) > 100:
        return -1
    return count

