def count_subarrays_with_sum(nums: list[int], target_sum: int) -> int:
    prefix_counts = {0: 1}
    current_sum = 0
    total_subarrays = 0
    for x in nums:
        current_sum += x
        diff = current_sum - target_sum
        if diff in prefix_counts:
            total_subarrays += prefix_counts[diff]
        prefix_counts[current_sum] = prefix_counts.get(current_sum, 0) + 1
    return total_subarrays

