from collections import defaultdict

def group_anagrams(words: list[str]) -> list[list[str]]:
    groups = defaultdict(list)
    for w in words:
        key = ''.join(sorted(w))
        groups[key].append(w)
    result = [sorted(g) for g in groups.values()]
    return sorted(result, key=lambda x: x[0] if x else '')

